    excerpt: 'Lạc tiên, tâm sen, bình vôi, táo nhân — những vị thuốc quen thuộc trong YHCT có tác dụng an thần nhẹ, cải thiện giấc ngủ theo cơ chế tự nhiên mà không gây lệ thuộc hay tác dụng phụ.',
