    excerpt: 'Túc Tam Lý là một trong những huyệt quan trọng bậc nhất trong châm cứu — có tác dụng bổ toàn thân, tăng miễn dịch và điều trị nhiều bệnh từ tiêu hóa đến hệ miễn dịch.',
