    excerpt: 'Thiên Vương Bổ Tâm Đan là bài thuốc YHCT hàng đầu điều trị mất ngủ, lo âu, hồi hộp do tâm huyết bất túc. Với 14 vị thuốc phối hợp tinh tế, bài thuốc vừa dưỡng tâm, vừa bổ thận, vừa an thần bền vững.',
