    excerpt: 'Linh chi (Ganoderma lucidum) có hàng nghìn năm sử dụng trong YHCT. Nghiên cứu hiện đại xác nhận một số tác dụng quan trọng — nhưng cũng có nhiều tuyên bố phóng đại cần biết để tránh lừa đảo.',
