<li><strong>Đàm thấp (béo, da nhờn, đầu nặng):</strong> Tăng: ý dĩ, đậu đỏ, khổ qua, hành tây, tảo biển. Tránh: đồ béo, ngọt, bia rượu, đồ ăn đêm.</li>
