<li><strong>Dưỡng tâm:</strong> Đọc sách, học điều mới, giao tiếp xã hội — "dưỡng thần" trong YHCT. Cô đơn xã hội là yếu tố nguy cơ lớn cho sức khỏe tổng thể.</li>
